const sourceConnectorsByIDs = `-- name: SourceConnectorsByIDs :many
SELECT id, credentials_cipher, credentials_set_at, credentials_set_by, schedule, cursor, cursor_at, last_complete_at FROM source_connectors WHERE id = ANY($1::uuid[])
`

func (q *Queries) SourceConnectorsByIDs(ctx context.Context, ids []uuid.UUID) ([]SourceConnector, error) {
	rows, err := q.db.Query(ctx, sourceConnectorsByIDs, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SourceConnector{}
	for rows.Next() {
		var i SourceConnector
		if err := rows.Scan(
			&i.ID,
			&i.CredentialsCipher,
			&i.CredentialsSetAt,
			&i.CredentialsSetBy,
			&i.Schedule,
			&i.Cursor,
			&i.CursorAt,
			&i.LastCompleteAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

